const R = String.raw;

export default [
  {
    id: 'mlops', title: 'MLOps and model deployment', tracks: ['mlops', 'mle', 'genai', 'ds'],
    tasks: [
      {
        id: 'ops-psi', title: 'Drift: population stability index',
        prompt: `PSI measures how far a feature's distribution in production has moved from training. Write \`psi(expected_counts, actual_counts, eps=1e-6)\` for two lists of counts over the same bins.

- Convert each list to proportions.
- Replace any proportion below \`eps\` with \`eps\` (avoids log of zero).
- \`psi = sum((a - e) * ln(a / e))\`

Rule of thumb: below 0.1 is stable, above 0.25 is a significant shift.`,
        starter: R`import math

def psi(expected_counts, actual_counts, eps=1e-6):
    pass

print(psi([50, 50], [70, 30]))  # about 0.169
`,
        solution: R`import math

def psi(expected_counts, actual_counts, eps=1e-6):
    te, ta = sum(expected_counts), sum(actual_counts)
    total = 0.0
    for e, a in zip(expected_counts, actual_counts):
        pe = max(e / te, eps)
        pa = max(a / ta, eps)
        total += (pa - pe) * math.log(pa / pe)
    return total
`,
        tests: [
          { name: 'Identical distributions', code: R`assert close(psi([10, 20, 30], [100, 200, 300]), 0.0), 'Same proportions give 0, whatever the sample size'` },
          { name: 'Shifted distribution', code: R`assert close(psi([50, 50], [70, 30]), 0.1694596, 1e-5), 'Expected about 0.1695'` },
          { name: 'Symmetric', code: R`assert close(psi([50, 50], [70, 30]), psi([70, 30], [50, 50])), 'PSI is the same in both directions'` },
          { name: 'Empty bin does not crash', code: R`import math
v = psi([50, 50, 0], [40, 40, 20])
assert math.isfinite(v) and v > 0.25, 'An empty bin must be clipped to eps, and this shift is significant'` }
        ]
      },
      {
        id: 'ops-percentile', title: 'Latency percentile',
        prompt: `Service latency is reported as p50, p95 and p99, not as the mean. Write \`percentile(values, q)\` using the nearest-rank method:

- Sort the values.
- \`rank = ceil(q * n / 100)\`, with a minimum of 1.
- Return the value at that rank (rank 1 is the smallest).`,
        starter: R`import math

def percentile(values, q):
    pass

print(percentile([120, 80, 95, 300, 110], 95))  # 300
`,
        solution: R`import math

def percentile(values, q):
    ordered = sorted(values)
    rank = max(1, math.ceil(q * len(ordered) / 100))
    return ordered[rank - 1]
`,
        tests: [
          { name: 'p95 of 1..100', code: R`assert percentile(list(range(1, 101)), 95) == 95, 'The 95th percentile of 1..100 is 95'` },
          { name: 'Median of unsorted values', code: R`assert percentile([5, 1, 3], 50) == 3, 'Sort first: the median of [5, 1, 3] is 3'` },
          { name: 'Tail is dominated by outliers', code: R`assert percentile([120, 80, 95, 300, 110], 95) == 300 and percentile([120, 80, 95, 300, 110], 100) == 300, 'With five values p95 is the largest'` },
          { name: 'Edge cases', code: R`assert percentile([10], 99) == 10 and percentile([4, 2, 9], 0) == 2, 'One value returns itself; q = 0 returns the minimum'` }
        ]
      }
    ],
    quiz: [
      { q: 'Data drift versus concept drift?', options: ['They are the same', 'Data drift: inputs change. Concept drift: the relation between inputs and target changes', 'Concept drift only affects images', 'Data drift is a bug'], answer: 1, why: 'Input drift can be detected without labels; concept drift usually needs fresh labels or proxy metrics.', level: 'easy' },
      { q: 'A model has great offline metrics but performs badly once deployed. A common cause?', options: ['Too many tests', 'Training-serving skew: features are computed differently online', 'Using Docker', 'A slow GPU'], answer: 1, why: 'Share feature code between training and serving, or use a feature store, and log online features.', level: 'medium' },
      { q: 'Safest way to roll out a new model version?', options: ['Replace the old one at midnight', 'Shadow or canary deployment with monitoring and a fast rollback', 'Email the model to users', 'Deploy on Friday'], answer: 1, why: 'Shadow mode compares predictions without affecting users; canary exposes a small share of traffic.', level: 'easy' },
      { q: 'What must be versioned to reproduce a model?', options: ['Only the code', 'Code, data, configuration and the environment', 'Only the weights', 'Nothing'], answer: 1, why: 'Tools: Git, DVC or a data catalogue, MLflow, container images.', level: 'medium' },
      { q: 'Why monitor p95 or p99 latency and not the mean?', options: ['The mean is illegal', 'A few slow requests ruin user experience and are hidden by the mean', 'Percentiles are easier to compute', 'The mean is always higher'], answer: 1, why: 'Service-level objectives are normally set on tail latency.', level: 'easy' },
      { q: 'What is a canary release?', options: ['Training on a small dataset', 'Releasing only on Fridays', 'Sending a small share of live traffic to the new model first', 'Running the model on a laptop'], answer: 2, why: 'You learn how it behaves on real traffic while limiting harm.', level: 'easy' },
      { q: 'A feature "country" is suddenly 30% null after an upstream change. Which monitor catches it first?', options: ['GPU utilisation', 'Training loss curves', 'The model’s file size', 'Data-quality checks on schema and null rates'], answer: 3, why: 'Input checks catch a broken feed before accuracy falls.', level: 'medium' },
      { q: 'A team retrains weekly and promotes automatically. Which gate protects against regressions?', options: ['Comparing the candidate with the production model on a fixed evaluation set and blocking if worse', 'Checking that training finished', 'Checking the container size', 'Counting the training epochs'], answer: 0, why: 'Promotion must depend on measured quality, not on completion.', level: 'medium' },
      { q: 'Mean latency is 40 ms and p99 is 1.2 s, with 1,000,000 requests a day. About how many requests a day take 1.2 s or more?', options: ['About 1,000', 'About 10,000', 'About 100,000', 'About 1.2 million'], answer: 1, why: '1% of 1,000,000 is 10,000: the tail is large in absolute terms.', level: 'hard' },
      { q: 'Offline AUC is 0.93 and live AUC is 0.74. The training feature days_since_last_order was computed with the full history, including orders after the prediction date. What is this?', options: ['Concept drift', 'Underfitting', 'Leakage: the feature used information from after the prediction time', 'A slow network'], answer: 2, why: 'Live, the future orders do not exist yet.', level: 'hard' },
      { q: 'The PSI of one input feature is 0.4, but a quality proxy is stable. Best action?', options: ['Investigate: the shift may be harmless or a sign of an upstream bug, so check its impact before retraining', 'Retrain immediately and ship', 'Ignore it for ever', 'Delete the feature from the dashboard'], answer: 0, why: 'A drift score is a prompt to look, not an automatic trigger.', level: 'hard' },
      { q: 'When would you choose a shadow deployment before a canary?', options: ['When the model is tiny', 'When you have no monitoring', 'When you want users to notice the change', 'When a wrong prediction would be costly or irreversible, so you want to compare on live traffic without acting on it'], answer: 3, why: 'Shadow predictions are logged but never acted on.', level: 'hard' }
    ],
    interview: [
      { q: 'Walk me through taking a model from a notebook to production.', level: 'medium', points: [['Package the code and pin the environment', ['package', 'docker', 'container', 'environment', 'refactor']], ['Tests and a reproducible training pipeline', ['test', 'pipeline', 'reproduc', 'ci']], ['Serve: API, batch or edge, to meet latency needs', ['api', 'serv', 'batch', 'endpoint', 'fastapi']], ['Roll out gradually: shadow or canary', ['shadow', 'canary', 'gradual', 'a/b', 'rollback']], ['Monitor quality, drift and latency; plan retraining', ['monitor', 'drift', 'retrain', 'alert']]], model: 'I move the notebook code into versioned, tested modules and make training a reproducible pipeline with pinned dependencies, versioned data and tracked experiments. I register the model with its metrics and package the inference code in a container, served as an API for real-time use or as a batch job if latency does not matter. CI/CD runs tests and builds the image. I release in shadow mode or as a canary, compare against the current model and keep a rollback ready. In production I monitor latency, errors, input drift and prediction quality, and I define when to retrain. Ownership and documentation are part of the job.' },
      { q: 'How do you monitor a model in production?', level: 'medium', points: [['System metrics: latency, throughput, errors', ['latency', 'error', 'throughput', 'uptime']], ['Input data quality and drift', ['drift', 'data quality', 'distribution', 'schema', 'missing']], ['Prediction distribution', ['prediction', 'output distribution', 'score distribution']], ['Real performance once labels arrive, or proxies', ['label', 'ground truth', 'proxy', 'business metric', 'feedback']], ['Alerts and a retraining or rollback plan', ['alert', 'retrain', 'rollback', 'threshold']]], model: 'I monitor at four levels. Service health: latency percentiles, error rate and throughput. Data quality: schema checks, missing values and drift in feature distributions against the training baseline, using measures such as PSI. Model outputs: the distribution of predictions and confidence. And true performance: when labels arrive, even with a delay, I compute the real metrics, and until then I watch proxy and business metrics. Each has thresholds and alerts, with a runbook that says when to investigate, roll back or retrain.' },
      { q: 'How would you serve a model that must answer in under 50 milliseconds?', level: 'hard', points: [['Measure first: where the time goes', ['measure', 'profil', 'bottleneck']], ['Make the model cheaper: smaller, quantised, distilled', ['quanti', 'distil', 'smaller', 'prun']], ['Optimised runtime and hardware', ['onnx', 'tensorrt', 'gpu', 'runtime', 'compiled']], ['Precompute and cache features or results', ['cache', 'precompute', 'feature store']], ['Batching, autoscaling, tail latency', ['batch', 'autoscal', 'p99', 'p95', 'tail', 'replica']]], model: 'I start by profiling the whole request to see how much time is network, feature lookup, preprocessing and model inference. Often the model is not the bottleneck. I precompute features and cache hot results. For the model I use an optimised runtime such as ONNX Runtime or TensorRT, quantise it, and if needed distil to a smaller architecture. I choose hardware to fit, use dynamic batching if throughput matters, keep instances warm and autoscale. I track p95 and p99, not the average, and I have a fallback, such as a simpler model, for when the budget is exceeded.' },
      { q: 'What is the difference between data drift and concept drift?', level: 'easy', points: [['Data drift: the distribution of the inputs changes', ['input', 'feature', 'distribution', 'data drift', 'covariate']], ['Concept drift: the relationship between inputs and the target changes', ['relationship', 'concept', 'target', 'label', 'meaning', 'mapping']], ['Examples: a new customer segment versus changing fraud behaviour or user taste', ['example', 'fraud', 'season', 'segment', 'behaviour', 'behavior', 'taste', 'new']], ['Detect with statistical tests and monitoring; concept drift needs fresh labels', ['detect', 'test', 'monitor', 'statistic', 'label', 'psi', 'ks', 'performance']]], model: 'Data drift means the distribution of the inputs has changed, for example a new group of customers, a new camera or a changed sensor, so the model sees data unlike its training set. Concept drift means the relationship between the inputs and the target has changed: the same input now deserves a different prediction, for instance when fraudsters adopt new tactics or customer taste shifts. Data drift I can detect without labels, by comparing feature distributions with a statistical test or a population stability index. Concept drift usually only shows up as falling performance once labels arrive. Either can trigger an investigation, retraining or a rollback.' },
      { q: 'What are experiment tracking and a model registry, and why do teams use them?', level: 'easy', points: [['Experiment tracking records parameters, code version, data version and metrics for each run', ['parameter', 'metric', 'run', 'code version', 'data version', 'record', 'log']], ['It makes results reproducible and comparable', ['reproduc', 'compar', 'repeat', 'trace']], ['A model registry stores versioned models with their stage such as staging or production', ['registry', 'version', 'stage', 'staging', 'production', 'store']], ['It supports approval, rollback and audit of what is deployed', ['approv', 'rollback', 'roll back', 'audit', 'lineage', 'deployed', 'governance']]], model: 'Experiment tracking logs everything about a training run: the hyperparameters, code commit, dataset version, metrics and artefacts. Without it, nobody can say which run produced the good model or reproduce it later. A model registry is the catalogue of trained models. Each version is stored with its metadata and a stage, such as candidate, staging or production, and it links back to the run that created it. Together they give me traceability: I always know what is deployed, which data trained it, and I can approve a promotion, audit the history or roll back to the previous version in minutes.' },
      { q: 'How is CI/CD for machine learning different from CI/CD for ordinary software?', level: 'easy', points: [['In ML, data and models change as well as code, so all three must be versioned and tested', ['data', 'model', 'code', 'version', 'three', 'also']], ['Extra tests: data validation, training smoke tests and model quality gates against a baseline', ['data validation', 'quality gate', 'baseline', 'metric', 'smoke', 'threshold', 'test']], ['Training pipelines are automated and may be triggered by new data or drift, not only by commits', ['pipeline', 'trigger', 'retrain', 'new data', 'drift', 'automat', 'schedule']], ['Deployment uses gradual rollout and monitoring, since model failures are often silent', ['gradual', 'canary', 'shadow', 'monitor', 'silent', 'rollout', 'rollback']]], model: 'In ordinary software the artefact changes only when code changes. In ML, the behaviour depends on code, data and the trained model, so all three must be versioned and tested. My pipeline adds data validation, a training run that is automated and reproducible, and quality gates that compare the new model against the current one on a fixed evaluation set and also on important slices. A retraining run can be triggered by new data or drift, not just by a commit. And because ML failures are often silent, with no exception thrown, I deploy gradually, using shadow or canary releases, and monitor quality after release.' },
      { q: 'How do you choose between batch, online and streaming inference?', level: 'medium', points: [['Batch: score many records on a schedule and store results; cheap and simple, but results are stale', ['batch', 'schedule', 'precompute', 'store', 'stale', 'cheap', 'offline']], ['Online: a request-response API with low latency for fresh, per-request predictions', ['online', 'real-time', 'real time', 'request', 'api', 'latency', 'fresh']], ['Streaming: continuously process events, for example for alerts or fraud', ['stream', 'event', 'continuous', 'kafka', 'alert', 'fraud']], ['Decide by freshness needs, latency, traffic, cost and the complexity you can run', ['freshness', 'latency', 'cost', 'traffic', 'complex', 'decide', 'need']]], model: 'It starts with how fresh the prediction must be. If the answer can wait, as with nightly churn scores or recommendations, batch inference is cheapest and simplest: I score everything on a schedule, store the results and look them up. If each request has unique input and needs an answer immediately, such as a fraud check at payment, I need online inference behind an API with a latency budget. If decisions react to a continuous event flow, such as sensor alerts, I use streaming. Online and streaming cost more to run and to keep reliable, so I choose the simplest mode that meets the business need.' },
      { q: 'Explain shadow deployment, canary release and A/B testing for models, and how rollback works.', level: 'medium', points: [['Shadow: the new model receives live traffic but its predictions are only logged, not used', ['shadow', 'logged', 'not used', 'silent', 'live traffic', 'compare']], ['Canary: send a small share of real traffic to the new model and increase if healthy', ['canary', 'small', 'percent', 'share', 'gradual', 'increase']], ['A/B test: compare business outcomes between versions with statistical rigour', ['a/b', 'business', 'outcome', 'statistic', 'compar', 'experiment', 'significan']], ['Rollback: keep the previous version deployed, switch traffic back quickly on bad metrics', ['rollback', 'roll back', 'previous', 'switch', 'revert', 'quick', 'automatic']]], model: 'Shadow deployment runs the new model on real traffic in parallel but only logs its predictions, so I can compare it with the live model at zero risk. A canary release then sends a small share of real traffic, say five percent, to the new model, and I increase it only if the metrics stay healthy. An A/B test goes further: I split users randomly and measure a business outcome with enough data to be statistically confident. For rollback I keep the previous version running and the traffic switch cheap, so if latency, errors or quality alarms fire I can revert in minutes, ideally automatically.' },
      { q: 'What is training-serving skew, and how do you prevent it?', level: 'hard', points: [['Features at serving time are computed differently from training, so the model sees different inputs', ['differ', 'different', 'mismatch', 'inconsisten', 'training', 'serving', 'features']], ['Causes: duplicated feature code, different libraries, missing values handled differently, time leakage', ['duplicate', 'code', 'library', 'missing', 'leak', 'time', 'cause']], ['Prevent with one shared feature pipeline or a feature store used for both', ['shared', 'feature store', 'same code', 'single', 'one pipeline', 'reuse']], ['Log served features and compare to training distributions; run back-to-back tests', ['log', 'compare', 'distribution', 'back-to-back', 'test', 'monitor', 'validate']], ['Use point-in-time correct data for training', ['point-in-time', 'point in time', 'time travel', 'leak', 'timestamp', 'historical']]], model: 'Training-serving skew means the model sees different feature values in production than it saw in training, even for the same entity. It often comes from two separate code paths: a data scientist writes pandas for training and an engineer rewrites it in another language for serving, with small differences in rounding, missing value handling or time windows. Another cause is leakage: training used data that was not yet available at prediction time. I prevent it with one shared feature definition, ideally a feature store that serves both offline and online, and point-in-time correct training data. I also log served features, compare them with training distributions and run back-to-back tests.' },
      { q: 'Your model accuracy seems to have dropped in production, but labels arrive weeks late. How do you investigate and decide whether to retrain?', level: 'hard', points: [['Check system health first: pipeline failures, missing or broken features, upstream changes', ['pipeline', 'upstream', 'missing', 'broken', 'schema', 'system', 'bug', 'health']], ['Monitor input drift and prediction distribution as label-free early signals', ['drift', 'distribution', 'prediction', 'label-free', 'proxy', 'input', 'early']], ['Use proxy metrics or sampled manual labelling to estimate performance sooner', ['proxy', 'sample', 'manual', 'label', 'estimate', 'feedback', 'business']], ['Evaluate on recent labelled data by slice to locate where it fails', ['slice', 'segment', 'recent', 'labelled', 'labeled', 'subgroup']], ['Retrain only when evidence shows real degradation; validate the new model against the old before rollout', ['retrain', 'validate', 'compare', 'evidence', 'rollout', 'champion', 'challenger']]], model: 'I start with the boring causes: a broken pipeline, missing features or a changed upstream schema, because these are more common than real drift. Then I use signals that need no labels: input drift, shifts in the prediction distribution and business proxies like conversion or complaint rates. To get ground truth sooner I label a small random sample by hand, or use any early feedback available. I evaluate recent labelled data by slice to see where it fails. If degradation is real, I retrain on fresh data and compare the new model with the current one on the same recent evaluation set, then roll out gradually.' }
    ]
  },

  {
    id: 'edge-deploy', title: 'Embedded and edge deployment', tracks: ['auto', 'cv', 'mlops', 'mle'],
    tasks: [
      {
        id: 'edge-quant', title: 'Int8 quantisation',
        prompt: `Affine quantisation maps a float to an 8-bit integer. Write two functions:

- \`quantize(values, scale, zero_point)\` returns a list of ints: \`q = round(x / scale) + zero_point\`, clipped to the range -128 to 127.
- \`dequantize(q_values, scale, zero_point)\` returns floats: \`x = (q - zero_point) * scale\`.`,
        starter: R`def quantize(values, scale, zero_point):
    pass

def dequantize(q_values, scale, zero_point):
    pass

print(quantize([0.0, 0.5, -0.5, 100.0], 0.01, 0))  # [0, 50, -50, 127]
`,
        solution: R`def quantize(values, scale, zero_point):
    return [int(max(-128, min(127, round(x / scale) + zero_point))) for x in values]

def dequantize(q_values, scale, zero_point):
    return [(q - zero_point) * scale for q in q_values]
`,
        tests: [
          { name: 'Quantise and clip', code: R`assert [int(v) for v in quantize([0.0, 0.5, -0.5, 100.0], 0.01, 0)] == [0, 50, -50, 127], 'Expected [0, 50, -50, 127]: values beyond the range saturate'
assert [int(v) for v in quantize([-9.0], 0.01, 0)] == [-128], 'Large negative values saturate at -128'` },
          { name: 'Zero point', code: R`assert [int(v) for v in quantize([0.1, 0.0], 0.05, 10)] == [12, 10], 'q = round(0.1 / 0.05) + 10 = 12; zero maps to the zero point'` },
          { name: 'Dequantise', code: R`assert close(dequantize([12, 10, -128], 0.05, 10), [0.1, 0.0, -6.9]), 'x = (q - zero_point) * scale'` },
          { name: 'Round-trip error is at most half a step', code: R`xs = [0.013, -0.247, 0.5, 0.999]
back = dequantize(quantize(xs, 0.01, 3), 0.01, 3)
assert all(abs(a - b) <= 0.005 + 1e-9 for a, b in zip(xs, back)), 'Quantise then dequantise should be within scale / 2'` }
        ]
      },
      {
        id: 'edge-params', title: 'Standard vs depthwise separable convolution',
        prompt: `Count parameters, **including biases**.

- \`conv_params(c_in, c_out, k)\`: a standard \`k×k\` convolution.
- \`separable_params(c_in, c_out, k)\`: a depthwise \`k×k\` convolution (one filter per input channel, with a bias per channel) followed by a pointwise 1×1 convolution to \`c_out\` channels (with biases).`,
        starter: R`def conv_params(c_in, c_out, k):
    pass

def separable_params(c_in, c_out, k):
    pass

print(conv_params(32, 64, 3), separable_params(32, 64, 3))  # 18496 2432
`,
        solution: R`def conv_params(c_in, c_out, k):
    return k * k * c_in * c_out + c_out

def separable_params(c_in, c_out, k):
    depthwise = k * k * c_in + c_in
    pointwise = c_in * c_out + c_out
    return depthwise + pointwise
`,
        tests: [
          { name: 'Standard convolution', code: R`assert conv_params(32, 64, 3) == 18496 and conv_params(3, 16, 5) == 1216, 'k*k*c_in*c_out weights plus c_out biases'` },
          { name: 'Separable convolution', code: R`assert separable_params(32, 64, 3) == 2432, 'Depthwise 9*32 + 32, pointwise 32*64 + 64'` },
          { name: 'Saving grows with kernel size', code: R`assert conv_params(64, 64, 5) / separable_params(64, 64, 5) > 15, 'A 5x5 separable convolution should be more than 15 times smaller here'` }
        ]
      }
    ],
    quiz: [
      { q: 'Post-training quantisation to int8 typically gives…', options: ['Higher accuracy', 'About 4× smaller model and faster inference, with a small accuracy loss', 'Slower inference', 'A larger model'], answer: 1, why: 'Weights go from 32-bit floats to 8-bit integers. Quantisation-aware training recovers accuracy when the loss is too large.', level: 'easy' },
      { q: 'What is a calibration dataset used for in quantisation?', options: ['Training from scratch', 'Estimating activation ranges to choose scales and zero points', 'Labelling', 'Testing latency'], answer: 1, why: 'It should be representative of real inputs, or the ranges will clip.', level: 'medium' },
      { q: 'After converting a model to C for a microcontroller, the first thing to verify is…', options: ['The font of the code', 'That outputs match the reference model on the same inputs, within tolerance', 'That it uses recursion', 'That it prints logs'], answer: 1, why: 'Bit-exact or tolerance-based back-to-back tests catch conversion and fixed-point errors.', level: 'hard' },
      { q: 'Knowledge distillation trains…', options: ['A large model from a small one', 'A small student to match the outputs of a large teacher', 'Two identical models', 'Only the last layer'], answer: 1, why: 'The soft targets carry more information than hard labels.', level: 'easy' },
      { q: 'Why is worst-case execution time important in embedded automotive software?', options: ['It reduces memory', 'Real-time tasks must always finish inside their time slot', 'It improves accuracy', 'It is a marketing number'], answer: 1, why: 'Average latency is not enough: a missed deadline can be a safety issue.', level: 'medium' },
      { q: 'Which is a good reason to run inference on the device rather than in the cloud?', options: ['Devices always have more compute than servers', 'It works without a network and the data stays local', 'It removes the need for testing', 'Models become more accurate'], answer: 1, why: 'Latency, connectivity and privacy favour the edge.', level: 'easy' },
      { q: 'What does pruning do?', options: ['Adds layers to improve accuracy', 'Converts floats to text', 'Increases the input resolution', 'Removes weights or channels that matter little'], answer: 3, why: 'A pruned model is smaller or faster, if structured well.', level: 'easy' },
      { q: 'A model has 8 MB of float32 weights and the device has 4 MB of flash. Which step gets closest to fitting?', options: ['int8 quantisation, which gives about 2 MB', 'Doubling the input resolution', 'Adding a layer', 'Using float64'], answer: 0, why: 'int8 uses a quarter of the bytes of float32.', level: 'medium' },
      { q: 'A model takes 45 ms on the device against a 33 ms budget, and 20 ms of that is resizing and colour conversion. First move?', options: ['Accept the miss', 'Only prune the network', 'Optimise the preprocessing, for example with hardware resize or a lower capture size', 'Increase the clock for a week'], answer: 2, why: 'Profile the whole pipeline: the network is not the main cost here.', level: 'medium' },
      { q: 'After int8 conversion accuracy drops by 12 points, but only on dark images. Likely cause?', options: ['The cable is loose', 'The calibration data lacked dark images, so activation ranges are wrong for them', 'The model has too few layers', 'The labels were shuffled'], answer: 1, why: 'Calibration must cover the conditions seen in the field.', level: 'hard' },
      { q: 'A camera runs at 30 fps. Per frame, preprocessing takes 8 ms, inference 22 ms and postprocessing 5 ms, one after another. Verdict and fix?', options: ['35 ms exceeds 33 ms; overlap the stages so throughput is limited by the slowest, 22 ms', 'It is fine, the average is low', 'Remove postprocessing from the product', 'Change the budget to 40 ms'], answer: 0, why: 'Pipelining stages raises throughput even though each frame still takes the sum.', level: 'hard' },
      { q: '80% unstructured pruning leaves the model’s CPU latency unchanged. Why?', options: ['Pruning always slows the CPU down', 'The CPU cannot read zeros', 'Accuracy dropped to zero', 'The zeros are still stored and multiplied by dense kernels unless sparse support exists'], answer: 3, why: 'Only structured pruning or sparse kernels turn zeros into speed.', level: 'hard' }
    ],
    interview: [
      { q: 'How do you deploy a Python-trained model to an embedded target in C?', level: 'medium', points: [['Simplify and fix the model: supported operators, fixed input size', ['simplif', 'supported', 'operator', 'fixed', 'freeze']], ['Convert: code generation or a hand-written inference in C', ['convert', 'generat', 'c code', 'port', 'export']], ['Quantise or use fixed-point arithmetic', ['quanti', 'fixed-point', 'fixed point', 'int8']], ['Verify equivalence with the Python model', ['verif', 'equivalen', 'match', 'compare', 'back-to-back', 'same output']], ['Measure memory, timing and integrate with the existing software', ['memory', 'ram', 'timing', 'latency', 'integrat', 'stack']]], model: 'I first make the model deployable: a small architecture, only operations the target supports and fixed input shapes. For a tree model I generate nested if-else code or lookup tables; for a neural network I use a code generator or write the inference loops in C. I convert to fixed-point or 8-bit integers if the processor has no fast floating point. Then I prove equivalence by running the same test vectors through the Python and C versions and comparing outputs within a tolerance. Finally I measure flash, RAM, stack and worst-case execution time on the target, integrate with the surrounding modules, and follow the coding standard and process the project requires, such as MISRA and ASPICE.' },
      { q: 'What techniques reduce model size and latency, and what are the trade-offs?', level: 'medium', points: [['Quantisation', ['quanti']], ['Pruning', ['prun']], ['Distillation', ['distil']], ['Efficient architectures or smaller inputs', ['mobilenet', 'efficient', 'architecture', 'depthwise', 'resolution']], ['Trade-off: accuracy, and hardware support', ['accuracy', 'trade', 'hardware', 'support']]], model: 'There are four main levers. Quantisation stores weights and activations as 8-bit integers, giving about four times less memory and faster inference for a small accuracy loss. Pruning removes weights or whole channels; structured pruning gives real speed-ups, unstructured pruning needs sparse support. Distillation trains a small student to imitate a large teacher. And architecture choices, such as depthwise separable convolutions or a lower input resolution, reduce compute at the source. Each trades some accuracy for efficiency, and what helps depends on the hardware, so I always measure on the target device.' },
      { q: 'How do you ensure quality for ML software in a regulated automotive project?', level: 'hard', points: [['Requirements with traceability to tests', ['requirement', 'traceab']], ['Process standards: ASPICE, ISO 26262, SOTIF', ['aspice', '26262', 'sotif', 'misra', 'standard']], ['Data management: versioned, documented datasets', ['data', 'dataset', 'version']], ['Verification at several levels, including on target', ['verif', 'unit test', 'integration', 'hil', 'on target', 'validation']], ['Reviews and configuration management', ['review', 'configuration', 'baseline', 'change']]], model: 'Quality starts with clear, testable requirements, each traced to design, implementation and test cases, as Automotive SPICE requires. For the ML part I treat data as a controlled work product: datasets are versioned, their coverage of operating conditions is documented and the split is frozen. Verification happens at several levels: unit tests of the code, back-to-back tests between the reference model and the embedded implementation, performance evaluation on a held-out set, and integration and vehicle tests. Changes go through review and configuration management. Where the function is safety-relevant, ISO 26262 and SOTIF analyses define what the model may and may not be trusted for.' },
      { q: 'Why run a model on the device instead of in the cloud?', level: 'easy', points: [['Low and predictable latency, with no network round trip', ['latency', 'round trip', 'network', 'fast', 'real-time', 'real time']], ['Works offline or with poor connectivity', ['offline', 'connectiv', 'reliab', 'availab', 'no network']], ['Privacy and bandwidth: raw data stays on the device', ['privacy', 'bandwidth', 'data stays', 'local', 'raw', 'sensitive']], ['Costs: limited compute, memory and power, and harder updates', ['limited', 'memory', 'power', 'compute', 'update', 'constraint', 'trade']]], model: 'There are four main reasons. Latency: a device decision does not wait for a network round trip, which matters for control loops and driver-facing features. Availability: it keeps working with no or poor connectivity, like in a tunnel or a remote site. Privacy and bandwidth: raw camera or sensor data does not have to leave the device, and I do not pay to upload it. And cost at scale, since inference runs on hardware the customer owns. The trade-offs are tight limits on compute, memory and power, and harder updates and monitoring, so the model must be small and the deployment process careful.' },
      { q: 'What are the main constraints of an embedded target compared with a server?', level: 'easy', points: [['Small memory: flash for the model and little RAM for activations', ['memory', 'ram', 'flash', 'small', 'kilobyte', 'megabyte', 'activation']], ['Limited compute: slower CPU, maybe no floating-point unit or GPU', ['compute', 'cpu', 'slow', 'fpu', 'floating', 'gpu', 'accelerator']], ['Power, heat and real-time deadlines', ['power', 'heat', 'thermal', 'battery', 'real-time', 'real time', 'deadline', 'energy']], ['Restricted software environment: no operating system or dynamic memory, a limited toolchain', ['operating system', 'os', 'dynamic', 'allocation', 'toolchain', 'static', 'compiler', 'library']]], model: 'A server has plentiful memory, strong processors, a GPU and a full operating system. An embedded target is the opposite. Memory is small: the model weights live in flash and the activations must fit into a few hundred kilobytes of RAM. The processor is slow and may have no floating-point unit or accelerator. Power and heat budgets are strict, and there are often hard real-time deadlines that must be met every cycle. The software environment is limited as well: perhaps no operating system, no dynamic memory allocation and a restricted compiler. So the whole design starts from these limits, not from model accuracy.' },
      { q: 'What does a model converter or inference runtime do on an edge device?', level: 'easy', points: [['A converter turns a trained framework model into a compact deployable format', ['convert', 'format', 'export', 'compact', 'deployable', 'translate']], ['It can fuse layers, quantise and optimise for the target hardware', ['fuse', 'fusion', 'quantis', 'quantiz', 'optimis', 'optimiz', 'hardware']], ['A runtime or generated code executes the model on the device with a small footprint', ['runtime', 'execute', 'generate', 'code', 'footprint', 'interpreter', 'engine']], ['You must check that the converted model matches the original and the operators are supported', ['verify', 'match', 'operator', 'support', 'accuracy', 'compare', 'check']]], model: 'A converter takes a model trained in a framework such as PyTorch or TensorFlow and turns it into a compact format for the device. On the way it can fuse layers, fold batch normalisation into weights, quantise and apply optimisations for the target hardware. A small runtime or generated C code then executes the model on the device with a minimal footprint. The risk is that conversion silently changes behaviour, or that an operator is not supported. So after converting I always run the same test inputs through the original and the deployed model, compare outputs against a tolerance, and check accuracy on the evaluation set.' },
      { q: 'How do you benchmark a model on the target device?', level: 'medium', points: [['Run on the real hardware, not a PC, with realistic inputs', ['real hardware', 'target', 'device', 'realistic', 'actual', 'on target']], ['Measure latency with warm-up, many runs and percentiles including worst case', ['latency', 'warm-up', 'warm up', 'repeat', 'percentile', 'worst', 'many runs', 'median']], ['Measure memory: flash for the model and peak RAM; and power or energy', ['memory', 'flash', 'ram', 'peak', 'power', 'energy']], ['Include preprocessing and postprocessing, and test under realistic system load', ['preprocess', 'postprocess', 'pipeline', 'load', 'end-to-end', 'end to end', 'full']]], model: 'I measure on the real hardware, with realistic inputs, because a PC says little about an embedded processor. For latency I do a warm-up, run many iterations and report the median, high percentiles and the worst case, since real-time systems care about the worst case. I measure memory two ways: flash for the model and code, and peak RAM for activations and buffers. Where it matters I also measure power or energy per inference. And I time the whole pipeline, including preprocessing and postprocessing, while the rest of the system is running, because a fast model alone does not meet the deadline.' },
      { q: 'How do you update models on a fleet of edge devices in the field?', level: 'medium', points: [['Deliver updates over the air with signed, versioned packages', ['over the air', 'ota', 'signed', 'version', 'package', 'secure', 'update']], ['Roll out in stages and keep the previous version for rollback', ['stage', 'staged', 'gradual', 'canary', 'rollback', 'roll back', 'previous', 'fallback']], ['Check compatibility between model, software and hardware versions', ['compatib', 'version', 'hardware', 'software', 'dependency', 'match']], ['Monitor after the update with telemetry that respects privacy', ['monitor', 'telemetry', 'privacy', 'metric', 'report', 'feedback']]], model: 'I treat a model update like a software release. It is built into a versioned, signed package and delivered over the air, and the device verifies the signature before installing. I roll out in stages, starting with a small group of devices, and the device keeps the previous version so it can roll back if the new one fails a self-check. I check compatibility between the model, the surrounding software and the hardware variant, because a mismatch can brick a feature. After release I collect telemetry, such as error counts, latency and confidence statistics, in a privacy-respecting way, and halt the rollout if something degrades.' },
      { q: 'Your model fits in flash but misses the 20 millisecond cycle time on the target. What do you do?', level: 'hard', points: [['Profile layer by layer to find the hot spots instead of guessing', ['profile', 'layer', 'hot spot', 'bottleneck', 'measure', 'where']], ['Quantise to integers and use hardware accelerators or optimised kernels', ['quantis', 'quantiz', 'integer', 'accelerator', 'optimised', 'optimized', 'kernel', 'simd', 'cmsis']], ['Shrink the model: pruning, a smaller architecture, distillation or lower input resolution', ['prun', 'smaller', 'distil', 'resolution', 'architecture', 'shrink']], ['Reduce the work: run less often, crop regions of interest, split work across cycles', ['less often', 'region', 'crop', 'split', 'frame rate', 'schedule', 'pipeline']], ['Re-check accuracy after each change and the final worst-case timing', ['accuracy', 're-check', 'worst', 'timing', 'verify', 'validate', 'regress']]], model: 'First I profile layer by layer on the target to see which operators eat the time, instead of guessing. Then I go for the cheap wins: quantise to eight-bit integers and use optimised kernels or the hardware accelerator, which often gives a large speed-up. If that is not enough I shrink the model: a lighter architecture, pruning, distillation, or a lower input resolution. I can also reduce the work, for example by processing only a region of interest, running at a lower rate, or splitting inference over several cycles. After each change I recheck accuracy on the evaluation set and measure worst-case timing, not just the average.' },
      { q: 'Design a model deployment process for a large fleet of devices where raw data cannot leave the device.', level: 'hard', points: [['Data stays local: on-device inference with privacy-preserving collection of aggregated metrics or selected, consented samples', ['local', 'on-device', 'on device', 'privacy', 'aggregate', 'consent', 'sample', 'anonymi']], ['Improve models through central training on permitted data, or federated learning', ['federated', 'central', 'permitted', 'simulation', 'synthetic', 'train']], ['A release pipeline with signing, staged rollout and rollback', ['sign', 'staged', 'rollout', 'rollback', 'pipeline', 'ota', 'version']], ['Monitor with on-device statistics such as confidence and input ranges to detect drift', ['monitor', 'statistic', 'confidence', 'drift', 'range', 'telemetry', 'health']], ['Test with simulation and replay of recorded data, plus a hardware-in-the-loop stage before release', ['simulation', 'replay', 'hardware-in-the-loop', 'hil', 'test', 'validation', 'lab']]], model: 'Because raw data stays on the device, I design for learning from little data. On the device I compute privacy-safe statistics, such as confidence histograms, input ranges and error counters, and upload only aggregates, plus a small consented set of samples where policy allows. Improvement comes from central training on data we may use, simulation and synthetic data, or federated learning if the benefit justifies its complexity. Releases go through a pipeline with testing on replayed recordings and hardware-in-the-loop, then signed packages, staged rollout and a rollback path. Fleet monitoring watches those aggregate statistics to detect drift and trigger the next model iteration.' }
    ]
  },

  {
    id: 'ml-system-design', title: 'ML system design', tracks: ['mle', 'genai', 'ds', 'mlops'],
    tasks: [
      {
        id: 'sd-ndcg', title: 'NDCG@k for ranking',
        prompt: `Ranking systems (search, recommendations) are scored with NDCG. Write \`ndcg_at_k(relevances, k)\`, where \`relevances\` are the graded relevance scores of the results in the order the system ranked them.

- \`DCG@k = sum(rel_i / log2(i + 2))\` for positions \`i = 0 .. k-1\`
- Ideal DCG is the DCG of the same scores sorted from highest to lowest.
- \`NDCG = DCG / ideal DCG\`. If the ideal DCG is 0, return \`0.0\`.`,
        starter: R`import math

def ndcg_at_k(relevances, k):
    pass

print(ndcg_at_k([0, 1], 2))  # about 0.631
`,
        solution: R`import math

def ndcg_at_k(relevances, k):
    def dcg(rels):
        return sum(r / math.log2(i + 2) for i, r in enumerate(rels[:k]))
    ideal = dcg(sorted(relevances, reverse=True))
    return dcg(relevances) / ideal if ideal > 0 else 0.0
`,
        tests: [
          { name: 'Perfect order', code: R`assert close(ndcg_at_k([3, 2, 1], 3), 1.0), 'Already sorted by relevance gives 1.0'` },
          { name: 'Relevant item ranked second', code: R`assert close(ndcg_at_k([0, 1], 2), 0.6309298, 1e-6), '1/log2(3) = 0.631'` },
          { name: 'Cut-off at k', code: R`assert close(ndcg_at_k([1, 0, 2], 2), 0.3800944, 1e-6), 'Only the first two positions count; the ideal order is [2, 1]'` },
          { name: 'Nothing relevant', code: R`assert close(ndcg_at_k([0, 0, 0], 3), 0.0), 'No relevant results gives 0.0 (no division by zero)'` }
        ]
      }
    ],
    quiz: [
      { q: 'First step in an ML system design interview?', options: ['Pick a model', 'Clarify the goal, users, scale and constraints', 'Draw the neural network', 'Choose a cloud provider'], answer: 1, why: 'Jumping to a model is the most common mistake. Agree the problem and the success metric first.', level: 'easy' },
      { q: 'A recommender must choose from 10 million items in 100 ms. Standard architecture?', options: ['Score all items with a deep model', 'Two stages: cheap candidate retrieval, then a precise ranking model on a few hundred', 'Random sampling', 'One SQL query'], answer: 1, why: 'Retrieval (embeddings and approximate nearest neighbours) narrows the set; ranking uses rich features.', level: 'medium' },
      { q: 'Why keep a simple baseline in a design discussion?', options: ['To waste time', 'It sets the bar, ships fast and shows whether complexity is worth it', 'Interviewers require it by law', 'It is always the best model'], answer: 1, why: 'For example popularity-based recommendations or a rules engine.', level: 'easy' },
      { q: 'A feature store mainly solves…', options: ['GPU shortages', 'Consistent features between training and serving, and reuse across teams', 'Model interpretability', 'Labelling'], answer: 1, why: 'It prevents training-serving skew and provides point-in-time correct features.', level: 'medium' },
      { q: 'A new model improves the offline metric but the A/B test is flat. Likely reason?', options: ['A/B tests are wrong', 'The offline metric is a weak proxy for the business goal, or there is feedback-loop bias in the logged data', 'Too many users', 'The model is too fast'], answer: 1, why: 'Logged data reflects what the old model showed. Validate proxies against online results.', level: 'hard' },
      { q: 'What is the cold-start problem?', options: ['The model is slow to load', 'The GPU is too cold', 'New users or items have no history to base predictions on', 'The dataset has no labels at all'], answer: 2, why: 'Fall back on popularity and content features.', level: 'easy' },
      { q: 'What is a guardrail metric in an A/B test?', options: ['A metric that must not get worse, such as latency or complaint rate, while you optimise the main one', 'The main metric you optimise', 'A metric used only offline', 'A metric measured before launch only'], answer: 0, why: 'It stops you winning on one number while harming another.', level: 'easy' },
      { q: 'A ranking model takes 5 ms per candidate, and you rank 2,000 candidates one by one within a 150 ms limit. What should you do?', options: ['Buy a longer timeout', 'Cut the candidates with a cheap first stage and score the rest in batches', 'Use the model on 10,000 candidates instead', 'Remove the latency limit'], answer: 1, why: '2,000 × 5 ms is 10 seconds; funnel down first.', level: 'medium' },
      { q: 'A fraud model labels everything legitimate and gets 99.9% accuracy when fraud is 0.1% of cases. Which metrics are better?', options: ['Accuracy only', 'Training time', 'Model file size', 'Precision and recall, or PR-AUC, weighted by the cost of errors'], answer: 3, why: 'Accuracy hides failure on rare classes.', level: 'medium' },
      { q: 'A recommender trained on its own clicks keeps showing the same popular items. Best fix?', options: ['Add exploration, for example randomised slots, and log the randomisation to correct for it', 'Train for more epochs', 'Remove all personalisation', 'Show fewer items'], answer: 0, why: 'The model needs data about items it never showed.', level: 'hard' },
      { q: 'A service gets 10,000,000 requests a day and peak is 5 times the average. About what are average and peak requests per second?', options: ['About 12 average and 60 peak', 'About 1,160 average and 5,800 peak', 'About 116 average and 580 peak', 'About 116 average and 116 peak'], answer: 2, why: '10,000,000 ÷ 86,400 ≈ 116; times 5 ≈ 580.', level: 'hard' },
      { q: 'Retrieval recall@100 is 0.6, while the ranker is excellent. What limits the whole system?', options: ['The ranker, as always', 'The ranker can only reorder what retrieval returns, so improve retrieval first', 'The database size', 'The user interface'], answer: 1, why: 'Missing candidates cannot be recovered later in the funnel.', level: 'hard' }
    ],
    interview: [
      { q: 'Design a recommendation system for an e-commerce app.', level: 'hard', points: [['Clarify goal, metric and scale', ['goal', 'metric', 'scale', 'clarif', 'requirement']], ['Data and features: users, items, interactions', ['interaction', 'click', 'purchase', 'feature', 'history']], ['Two-stage: candidate retrieval then ranking', ['candidate', 'retriev', 'rank', 'two-stage', 'two stage']], ['Cold start for new users and items', ['cold start', 'new user', 'new item', 'popular']], ['Evaluation offline and online, plus monitoring', ['a/b', 'online', 'offline', 'ndcg', 'monitor']]], model: 'I begin by clarifying the goal, for example increasing purchases, the surfaces involved, the scale and the latency budget. Data comes from interaction logs, such as views, carts and purchases, plus user and item attributes. I start with a popularity and co-purchase baseline. The target design has two stages: candidate retrieval with a two-tower embedding model and approximate nearest-neighbour search to get a few hundred items, then a ranking model, such as gradient-boosted trees or a neural ranker, using rich user, item and context features. I handle cold start with content features and popularity. I evaluate offline with recall at k and NDCG on a time-based split, then with an A/B test on conversion, and I monitor drift, diversity and feedback loops.' },
      { q: 'Design a system that answers employee questions from internal company documents.', level: 'hard', points: [['Clarify users, document types, languages and security', ['clarif', 'security', 'access', 'language', 'document type', 'permission']], ['Ingestion: parse, chunk, embed, index', ['chunk', 'embed', 'index', 'ingest']], ['Retrieval with access control, hybrid search and re-ranking', ['retriev', 'hybrid', 're-rank', 'rerank', 'access control']], ['Generation grounded in sources, with citations', ['citation', 'cite', 'ground', 'source']], ['Evaluation, monitoring, cost and latency', ['evaluat', 'monitor', 'cost', 'latency', 'feedback']]], model: 'I would clarify who uses it, what documents exist, in which languages, how fresh they must be and what access rules apply. The design is retrieval-augmented generation. An ingestion pipeline parses documents, chunks them, embeds them and stores vectors with metadata, including permissions, and re-indexes on change. At query time I retrieve with hybrid search filtered by the user’s permissions, re-rank and pass the top passages to the model with instructions to answer only from them and cite the source. If data cannot leave the company, I serve a local model. I build an evaluation set with real questions, measure retrieval recall and answer faithfulness, collect user feedback, and track cost and latency.' },
      { q: 'How do you decide whether a problem needs machine learning at all?', level: 'easy', points: [['Is there a clear business goal and metric', ['goal', 'metric', 'value', 'business']], ['Can rules or a simple heuristic solve it', ['rule', 'heuristic', 'simple']], ['Is there enough data of good quality, with labels', ['data', 'label']], ['Cost of errors and of maintenance', ['cost', 'maintain', 'error', 'risk']]], model: 'I ask four questions. Is there a clear outcome we want to improve and a way to measure it? Could rules or a simple heuristic get most of the value, and if so I start there. Do we have, or can we collect, enough representative data with reliable labels? And what do mistakes cost, and can we afford to monitor and maintain a model for years? ML is the right tool when the pattern is too complex for rules, data is available and the value clearly exceeds the running cost. Otherwise the simple solution is the better engineering decision.' },
      { q: 'How do you start an ML system design question?', level: 'easy', points: [['Clarify the business goal, the users and the constraints such as latency, scale and privacy', ['clarify', 'goal', 'user', 'constraint', 'latency', 'scale', 'requirement', 'privacy']], ['Define the prediction task and the success metric, both offline and business', ['task', 'metric', 'success', 'offline', 'business', 'target', 'define']], ['Check the data available, labels and how they arrive', ['data', 'label', 'available', 'source', 'feedback']], ['Sketch a simple baseline end to end first, then go deeper where it matters', ['baseline', 'simple', 'end to end', 'end-to-end', 'first', 'iterate', 'deeper']]], model: 'I do not jump to a model. I first ask questions: what business problem are we solving, who uses the output, and what constraints apply, such as latency, scale, privacy and cost. Then I define the prediction task precisely and the success metrics, both offline, like precision and recall, and the business metric that the model should move. I check which data exists, whether labels exist and how feedback comes back. Then I sketch a simple end-to-end baseline: data, features, model, serving and monitoring, before I go deep into the parts that matter most, and I say which trade-offs I am making.' },
      { q: 'How do you choose metrics for an ML system, offline versus online?', level: 'easy', points: [['Offline metrics such as precision, recall, AUC or ranking quality, chosen for the cost of errors', ['precision', 'recall', 'auc', 'offline', 'ranking', 'f1', 'error', 'cost']], ['Online and business metrics such as conversion, retention, revenue or complaint rate', ['online', 'business', 'conversion', 'retention', 'revenue', 'click', 'complaint']], ['Offline gains may not translate online, so validate with an A/B test', ['a/b', 'translate', 'validate', 'experiment', 'online test', 'correlat']], ['Add guardrail metrics: latency, fairness, cost and harm', ['guardrail', 'latency', 'fairness', 'cost', 'harm', 'safety', 'constraint']]], model: 'I use two layers. Offline metrics, computed on historical data, let me iterate quickly: precision and recall or an F-score for classification, and ranking metrics like NDCG for recommendations, chosen according to the cost of each type of error. Online and business metrics, such as conversion, retention, revenue or complaint rate, tell me whether the system actually helps. A better offline score does not always improve those, so I validate with an A/B test. I also define guardrail metrics that must not get worse, such as latency, cost, fairness across groups and harmful outputs, and I monitor them continuously.' },
      { q: 'Design a fraud detection system for card payments.', level: 'medium', points: [['Strict latency budget: score each transaction in tens of milliseconds, in real time', ['latency', 'real-time', 'real time', 'millisecond', 'score', 'transaction', 'online']], ['Features: transaction, user history, device, merchant and aggregated velocity features', ['feature', 'history', 'device', 'merchant', 'velocity', 'aggregate', 'behaviour', 'behavior']], ['Highly imbalanced and delayed labels: use suitable metrics, sampling or weights, and handle label lag', ['imbalanc', 'delay', 'label', 'precision', 'recall', 'weight', 'sampling', 'chargeback']], ['Combine rules and a model, with thresholds tuned to the cost of false positives versus misses', ['rule', 'threshold', 'false positive', 'cost', 'miss', 'block', 'review']], ['Adversaries adapt, so monitor drift, retrain often and add human review', ['adapt', 'adversar', 'drift', 'retrain', 'monitor', 'human', 'review', 'analyst']]], model: 'The system scores each transaction in real time within a tight latency budget, so features must be precomputed or cheap: transaction details plus recent history for the card, device and merchant, such as how many payments in the last hour. Fraud is rare and labels are delayed until chargebacks arrive, so I use class weights or sampling, evaluate with precision and recall at a chosen operating point, and train on time-based splits. A rules engine handles known patterns, a model scores the rest, and thresholds reflect the cost of blocking good customers versus missing fraud, with borderline cases going to analysts. Fraudsters adapt, so I monitor drift and retrain often.' },
      { q: 'Design a content moderation system for user posts.', level: 'medium', points: [['Clarify policies, categories, languages and content types such as text and images', ['policy', 'categor', 'language', 'text', 'image', 'type', 'clarify']], ['Pipeline: fast filters and models first, heavier models for uncertain cases', ['pipeline', 'filter', 'stage', 'cascade', 'fast', 'heavy', 'uncertain']], ['Thresholds by severity: auto-remove clear violations, send borderline cases to human reviewers', ['threshold', 'severity', 'human', 'review', 'borderline', 'auto', 'remove']], ['Labels from reviewers with clear guidelines, appeals and feedback into training', ['label', 'reviewer', 'guideline', 'appeal', 'feedback', 'quality', 'agreement']], ['Measure per category and per language; monitor fairness and adversarial evasion', ['category', 'language', 'fairness', 'adversar', 'evasion', 'measure', 'monitor', 'bias']]], model: 'I begin with the policy: which categories are prohibited, in which languages and in what formats. The system is a cascade. Cheap rules and a fast classifier handle the bulk of content, and expensive models, such as a large language model or an image model, look only at uncertain cases. Thresholds depend on severity: clear violations are removed automatically, borderline ones go to human reviewers, and users can appeal. Reviewer decisions with clear guidelines become training labels. I measure precision and recall per category and per language, watch for bias against certain groups, and monitor for users deliberately evading the filters.' },
      { q: 'What is a feature store and when is it worth using?', level: 'medium', points: [['A central place to define, compute, store and serve features for training and serving', ['central', 'define', 'store', 'serve', 'feature', 'training', 'serving']], ['It offers an offline store for training and a low-latency online store for inference', ['offline', 'online', 'low-latency', 'low latency', 'lookup', 'batch']], ['It prevents training-serving skew and gives point-in-time correct data', ['skew', 'point-in-time', 'point in time', 'consisten', 'leak']], ['It enables reuse and governance, but adds complexity, so use it with many models or teams', ['reuse', 'governance', 'complex', 'many', 'team', 'worth', 'overhead']]], model: 'A feature store is a shared system where features are defined once, computed by a pipeline, and served in two ways: an offline store with history for training and a low-latency online store for lookup at inference time. Its main benefit is consistency. Training and serving use the same definition, which avoids training-serving skew, and it can build point-in-time correct training sets to avoid leakage. It also lets teams discover and reuse features and gives governance and lineage. But it is extra infrastructure to run, so it pays off when several models or teams share features or when online serving needs consistent real-time features.' },
      { q: 'What is a feedback loop in a deployed ML system, and how can it cause problems?', level: 'medium', points: [['Model outputs influence the data that will later be used to train it', ['influence', 'output', 'data', 'train', 'later', 'own', 'affect']], ['Example: a recommender only shows popular items, so only those get clicks and become more popular', ['recommend', 'popular', 'click', 'example', 'shown', 'exposure', 'rich']], ['Consequences: bias, narrowing, self-fulfilling predictions and misleading metrics', ['bias', 'narrow', 'self-fulfilling', 'self fulfilling', 'misleading', 'echo', 'skew']], ['Mitigate with exploration, randomised holdouts, counterfactual or unbiased evaluation and monitoring diversity', ['explor', 'random', 'holdout', 'counterfactual', 'unbiased', 'diversity', 'monitor']]], model: 'A feedback loop appears when the model output changes the data it will later learn from. A recommender shows popular items, users can only click what they are shown, so those items get more clicks and look even better next training round, while good new items never get a chance. Similar effects occur in fraud or credit scoring, where we only see outcomes for approved cases. The result is bias, a narrowing of results and metrics that look healthy while the system is blind. I mitigate with exploration, a small randomised holdout for unbiased data, careful counterfactual evaluation, and monitoring diversity and coverage.' },
      { q: 'Design a predictive maintenance system for a fleet of vehicles using sensor data.', level: 'hard', points: [['Define the target: failure within a horizon, with cost of missed failures versus false alarms', ['target', 'failure', 'horizon', 'label', 'cost', 'false alarm', 'define', 'predict']], ['Data: telemetry streams, maintenance records for labels, and usage context; handle missing and noisy data', ['telemetry', 'sensor', 'record', 'label', 'noisy', 'missing', 'context', 'usage']], ['Edge versus cloud: compute features on the vehicle, send summaries, train and score in the cloud', ['edge', 'cloud', 'vehicle', 'summar', 'bandwidth', 'upload', 'on-board', 'on board']], ['Models: start with baselines and anomaly detection, time-based validation, rare failure events', ['baseline', 'anomaly', 'time-based', 'time based', 'imbalanc', 'rare', 'validation', 'survival']], ['Operate: alert thresholds, workshop integration, monitoring and a feedback loop from repairs', ['alert', 'workshop', 'integrat', 'monitor', 'feedback', 'repair', 'retrain']]], model: 'First, define the prediction: probability of a specific failure within the next few weeks, because the useful horizon and the cost of missed failures versus false alarms drive everything. Data comes from vehicle telemetry plus maintenance records for labels, and labels are rare and noisy. To save bandwidth, the vehicle computes features and summaries on board and uploads them. In the cloud I begin with simple baselines and anomaly detection, validate with time-based splits per vehicle, and handle imbalance. Alerts are thresholded and integrated with workshop scheduling. I monitor drift across vehicle variants and feed repair outcomes back as new labels.' }
    ]
  }
];
